var i=123;var a=[{id:`cooking-123-01`,theoryId:123,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Why can milk scorch on the bottom of a very hot pot?`,ua:`Чому молоко може пригоряти на дні дуже гарячої каструлі?`},explanation:{en:`Whey proteins and milk solids can deposit on the hot surface and scorch.`,ua:`Сироваткові білки та сухі речовини молока можуть осідати на гарячому дні й пригорати.`},options:[{id:`a`,text:{en:`Sensitive milk proteins adhere and overheat`,ua:`Чутливі молочні білки прилипають і перегріваються`}},{id:`b`,text:{en:`Milk contains only pure water`,ua:`Молоко містить лише воду`}},{id:`c`,text:{en:`The fat becomes table salt`,ua:`Жир перетворюється на кухонну сіль`}}],answer:{optionIds:[`a`]}},{id:`cooking-123-02`,theoryId:123,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`High heat and added acid can encourage milk proteins to aggregate or curdle.`,ua:`Сильний нагрів і додана кислота можуть сприяти зсіданню молочних білків.`},explanation:{en:`Protein stability changes with both temperature and pH.`,ua:`Стабільність білків залежить від температури й pH.`},answer:{value:!0}},{id:`cooking-123-03`,theoryId:123,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match milk observations to likely mechanisms.`,ua:`Поєднайте ознаки молока з імовірними процесами.`},explanation:{en:`Heat and acidity influence milk protein behavior.`,ua:`Тепло та кислотність змінюють поведінку молочних білків.`},leftItems:[{id:`l1`,text:{en:`Bottom scorches`,ua:`Молоко пригорає на дні`}},{id:`l2`,text:{en:`Lemon causes clumps`,ua:`Лимон утворює грудочки`}},{id:`l3`,text:{en:`Gentle stirring while heating`,ua:`Обережне помішування`}}],rightItems:[{id:`r3`,text:{en:`Reduces hot spots`,ua:`Зменшує локальний перегрів`}},{id:`r2`,text:{en:`Acid-driven protein aggregation`,ua:`Кислотна агрегація білків`}},{id:`r1`,text:{en:`Localized overheating`,ua:`Локальний перегрів`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-123-04`,theoryId:123,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A milk-based soup repeatedly sticks and burns. What change helps?`,ua:`Молочний суп постійно прилипає й пригорає. Що допоможе?`},explanation:{en:`Moderate heating and mixing reduce scorching risks.`,ua:`Помірний нагрів і перемішування знижують ризик пригорання.`},options:[{id:`a`,text:{en:`Lower heat, use a heavy pan and stir`,ua:`Зменшити нагрів, взяти посуд із товстим дном і помішувати`}},{id:`b`,text:{en:`Use maximum heat without stirring`,ua:`Вмикати максимальний нагрів без перемішування`}},{id:`c`,text:{en:`Add raw flour at the last second`,ua:`В останню мить додати сире борошно`}}],answer:{optionIds:[`a`]}},{id:`cooking-123-05`,theoryId:123,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which statement about curdled milk is incorrect?`,ua:`Яке твердження про зсіле молоко неправильне?`},explanation:{en:`Intentional acid coagulation makes cheese; unwanted curdling can also arise from heat and acidity.`,ua:`Цілеспрямоване зсідання кислотою застосовують у сироробстві, а випадкове може бути спричинене нагрівом і кислотою.`},options:[{id:`a`,text:{en:`Acidity can change casein behavior`,ua:`Кислотність може змінювати поведінку казеїну`}},{id:`b`,text:{en:`Overheating can damage texture`,ua:`Перегрів може зіпсувати текстуру`}},{id:`c`,text:{en:`All curdling always proves microbial spoilage`,ua:`Будь-яке зсідання завжди доводить мікробне псування`}}],answer:{optionIds:[`c`]}}];var n={theoryId:123,exercises:a};export{n as default,a as exercises,i as theoryId};